def hexrgb(h):
    b = bytes.fromhex(h)
    return [tuple(b[i:i + 3]) for i in range(0, len(b), 3)]


def night_class(rgb):
    r, g, b = rgb
    edge = min(1.0, max(0.0, 1.0 - abs(b - 120.0) / 110.0)) * min(1.0, max(0.0, (r - 150) / 80.0))
    hi = min(1.0, max(0.0, (g - 95.0) / 70.0))
    n = 0
    if edge > 0.15: n = 2
    if edge > 0.4: n = 3
    if edge > 0.65: n = 4
    if edge > 0.85: n = 5
    if hi > 0.35: n = 7 if b > 128 else 6
    if n == 0 and r > 200 and b < 60: n = 1
    return n


def rgb_to_hw10(rgb):
    r, g, b = [c / 255.0 for c in rgb]
    y = 0.299 * r + 0.587 * g + 0.114 * b
    cb = (b - y) / 1.772
    cr = (r - y) / 1.402
    return (64 + y * 876, 512 + cr * 896, 512 + cb * 896)


def pack(rgb, low4=0):
    y, u, v = rgb_to_hw10(rgb)
    y = 64 + (y - 64) * 16 / 13
    yi = max(64, min(940, int(round(y))))
    ui = max(0, min(511, int(round(u / 2))))
    vi = max(0, min(511, int(round(v / 2))))
    return (yi << 22) | (ui << 13) | (vi << 4) | (low4 & 15)


